INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15932, 'Wetherspoons Bans Phone Music and Speaker Calls in Pubs', 'व्हिtherspoons ने पब में फोन पर संगीत और स्पीकर कॉल बजाने पर प्रतिबंध लगाया', 'The UK pub chain Wetherspoons has banned customers from playing music or taking phone calls on speakerphone in its venues. The company stated the decision was made following numerous complaints about noise from "other people''s videos and amplified phone conversations." Wetherspoons aims to create an "oasis of tranquillity" for its patrons.', 'यूके की पब श्रृंखला व्हिtherspoons ने अपने प्रतिष्ठानों में ग्राहकों द्वारा फोन पर संगीत बजाने या स्पीकरफ़ोन पर कॉल लेने पर प्रतिबंध लगा दिया है। कंपनी ने कहा कि यह निर्णय "अन्य लोगों के वीडियो और प्रवर्धित फोन वार्तालापों" से होने वाले शोर के बारे में कई शिकायतों के बाद लिया गया। व्हिtherspoons का लक्ष्य अपने संरक्षकों के लिए "शांति का नखलिस्तान" बनाना है।', '["Wetherspoons has implemented a ban on playing music from phone speakers.", "Customers are also prohibited from taking phone calls on speakerphone.", "The ban was introduced due to customer complaints about noise.", "Specific complaints cited \"other people''s videos and amplified phone conversations.\"", "The company described its venues as an \"oasis of tranquillity.\""]'::jsonb, '["व्हिtherspoons ने फोन स्पीकर से संगीत बजाने पर प्रतिबंध लगा दिया है।", "ग्राहकों को स्पीकरफ़ोन पर फोन कॉल लेने से भी मना किया गया है।", "यह प्रतिबंध शोर के बारे में ग्राहकों की शिकायतों के कारण पेश किया गया था।", "विशिष्ट शिकायतों में \"अन्य लोगों के वीडियो और प्रवर्धित फोन वार्तालाप\" का उल्लेख किया गया था।", "कंपनी ने अपने प्रतिष्ठानों को \"शांति का नखलिस्तान\" बताया है।"]'::jsonb, 'Society', 'World', 1, 1, 0, 0, 0, 2, 'left', 50, NULL, NULL, '{"left": {"count": 1, "sources": ["The Guardian"], "owners": ["The Guardian"]}, "center": {"count": 1, "sources": ["BBC News"], "owners": ["BBC News"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{}'::jsonb, '{}'::jsonb, '[{"source": "The Guardian", "owner": "The Guardian", "lean": "left", "language": "en", "url": "https://www.theguardian.com/business/2026/aug/18/wetherspoons-pubs-ban-music-calls-phone-speakers", "headline": "Wetherspoons pubs ban playing music or taking calls on phone speakers"}, {"source": "BBC News", "owner": "BBC News", "lean": "center", "language": "en", "url": "https://www.bbc.co.uk/news/articles/cnvnl8gy22lo", "headline": "Wetherspoons bans customers playing music from phones in pubs"}]'::jsonb, '{"title": "Wetherspoons Bans Phone Music and Speaker Calls in Pubs", "summary": "The UK pub chain Wetherspoons has banned customers from playing music or taking phone calls on speakerphone in its venues. The company stated the decision was made following numerous complaints about noise from \"other people''s videos and amplified phone conversations.\" Wetherspoons aims to create an \"oasis of tranquillity\" for its patrons.", "summary_points": ["Wetherspoons has implemented a ban on playing music from phone speakers.", "Customers are also prohibited from taking phone calls on speakerphone.", "The ban was introduced due to customer complaints about noise.", "Specific complaints cited \"other people''s videos and amplified phone conversations.\"", "The company described its venues as an \"oasis of tranquillity.\""], "title_hi": "व्हिtherspoons ने पब में फोन पर संगीत और स्पीकर कॉल बजाने पर प्रतिबंध लगाया", "summary_hi": "यूके की पब श्रृंखला व्हिtherspoons ने अपने प्रतिष्ठानों में ग्राहकों द्वारा फोन पर संगीत बजाने या स्पीकरफ़ोन पर कॉल लेने पर प्रतिबंध लगा दिया है। कंपनी ने कहा कि यह निर्णय \"अन्य लोगों के वीडियो और प्रवर्धित फोन वार्तालापों\" से होने वाले शोर के बारे में कई शिकायतों के बाद लिया गया। व्हिtherspoons का लक्ष्य अपने संरक्षकों के लिए \"शांति का नखलिस्तान\" बनाना है।", "summary_points_hi": ["व्हिtherspoons ने फोन स्पीकर से संगीत बजाने पर प्रतिबंध लगा दिया है।", "ग्राहकों को स्पीकरफ़ोन पर फोन कॉल लेने से भी मना किया गया है।", "यह प्रतिबंध शोर के बारे में ग्राहकों की शिकायतों के कारण पेश किया गया था।", "विशिष्ट शिकायतों में \"अन्य लोगों के वीडियो और प्रवर्धित फोन वार्तालाप\" का उल्लेख किया गया था।", "कंपनी ने अपने प्रतिष्ठानों को \"शांति का नखलिस्तान\" बताया है।"], "framing": {}, "framing_hi": {}, "topic": "Society", "region": "World", "published_at": null, "image_url": "https://i.guim.co.uk/img/media/5467d3de7117b6127260420179080290ecc322ed/1120_0_5600_4480/master/5600.jpg?width=140&quality=85&auto=format&fit=max&s=28758178b614878f2729a33b2a7eef55", "sources": [{"source": "The Guardian", "owner": "The Guardian", "lean": "left", "language": "en", "url": "https://www.theguardian.com/business/2026/aug/18/wetherspoons-pubs-ban-music-calls-phone-speakers", "headline": "Wetherspoons pubs ban playing music or taking calls on phone speakers"}, {"source": "BBC News", "owner": "BBC News", "lean": "center", "language": "en", "url": "https://www.bbc.co.uk/news/articles/cnvnl8gy22lo", "headline": "Wetherspoons bans customers playing music from phones in pubs"}], "coverage": {"left": {"count": 1, "sources": ["The Guardian"], "owners": ["The Guardian"]}, "center": {"count": 1, "sources": ["BBC News"], "owners": ["BBC News"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}, "total_sources": 2, "degraded": false, "summary_method": "llm"}'::jsonb, 'https://i.guim.co.uk/img/media/5467d3de7117b6127260420179080290ecc322ed/1120_0_5600_4480/master/5600.jpg?width=140&quality=85&auto=format&fit=max&s=28758178b614878f2729a33b2a7eef55', FALSE, FALSE, 'llm', NULL, NULL, '2026-08-18T10:30:17.521717'::timestamptz) ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, title_hi = EXCLUDED.title_hi, summary = EXCLUDED.summary, summary_hi = EXCLUDED.summary_hi, summary_points = EXCLUDED.summary_points, summary_points_hi = EXCLUDED.summary_points_hi, topic = EXCLUDED.topic, region = EXCLUDED.region, lean_left = EXCLUDED.lean_left, lean_center = EXCLUDED.lean_center, lean_right = EXCLUDED.lean_right, international_count = EXCLUDED.international_count, unrated_count = EXCLUDED.unrated_count, total_sources = EXCLUDED.total_sources, dominant_lean = EXCLUDED.dominant_lean, dominant_pct = EXCLUDED.dominant_pct, blindspot_side = EXCLUDED.blindspot_side, blindspot_pct = EXCLUDED.blindspot_pct, coverage = EXCLUDED.coverage, framing = EXCLUDED.framing, framing_hi = EXCLUDED.framing_hi, sources = EXCLUDED.sources, analysis_json = EXCLUDED.analysis_json, image_url = EXCLUDED.image_url, is_demo = EXCLUDED.is_demo, degraded = EXCLUDED.degraded, summary_method = EXCLUDED.summary_method, storyline_id = EXCLUDED.storyline_id, published_at = EXCLUDED.published_at, created_at = EXCLUDED.created_at, synced_at = now();
INSERT INTO public.events (id, title, title_hi, summary, summary_hi, summary_points, summary_points_hi, topic, region, lean_left, lean_center, lean_right, international_count, unrated_count, total_sources, dominant_lean, dominant_pct, blindspot_side, blindspot_pct, coverage, framing, framing_hi, sources, analysis_json, image_url, is_demo, degraded, summary_method, storyline_id, published_at, created_at) VALUES (15931, 'Syrian court sentences Bashar al-Assad''s cousin to death', 'सीरियाई अदालत ने बशर अल-असद के चचेरे भाई को मौत की सजा सुनाई', 'A Syrian court in Damascus has sentenced Wassim al-Assad, a cousin of former Syrian ruler Bashar al-Assad, to death. He was found guilty of premeditated murder and torture. The conviction and sentencing occurred on Tuesday.', 'दमिश्क की एक सीरियाई अदालत ने पूर्व सीरियाई शासक बशर अल-असद के चचेरे भाई वासिम अल-असद को मौत की सजा सुनाई है। उन्हें पूर्व-नियोजित हत्या और यातना के आरोपों में दोषी पाया गया था। यह सजा मंगलवार को सुनाई गई।', '["Wassim al-Assad, cousin of Syrian ruler Bashar al-Assad, sentenced to death.", "Convicted of premeditated murder and torture.", "Sentencing by a Damascus court on Tuesday.", "Wassim al-Assad is a former regime figure."]'::jsonb, '["सीरियाई शासक बशर अल-असद के चचेरे भाई वासिम अल-असद को मौत की सजा सुनाई गई।", "उन्हें पूर्व-नियोजित हत्या और यातना के आरोपों में दोषी ठहराया गया।", "यह सजा मंगलवार को दमिश्क की एक अदालत ने सुनाई।", "वासिम अल-असद एक पूर्व शासन हस्ती हैं।"]'::jsonb, 'Crime & Law', 'World', 1, 1, 0, 0, 0, 2, 'left', 50, NULL, NULL, '{"left": {"count": 1, "sources": ["Al Jazeera English"], "owners": ["Al Jazeera English"]}, "center": {"count": 1, "sources": ["France 24"], "owners": ["France 24"]}, "right": {"count": 0, "sources": [], "owners": []}, "international": {"count": 0, "sources": []}, "unrated": {"count": 0, "sources": []}}'::jsonb, '{}'::jsonb, '{}'::jsonb, '[{"source": "Al Jazeera English", "owner": "Al Jazeera English", "lean": "left", "language": "en", "url": "https://www.aljazeera.com/news/2026/8/18/syrian-court-sentences-wassim-al-assad-to?traffic_source=rss", "headline": "Syrian court sentences Wassim al-Assad to death"}, {"source": "France 24", "owner": "France 24", "lean": "center", "language": "en", "url": "https://www.france24.com/en/middle-east/20260818-syria-sentences-to-death-assad-s-detained-cousin-for-war-crimes", "headline": "Syria sentences to death Assad''s detained cousin for war crimes"}]'::jsonb, '{"title": "Syrian court sentences Bashar al-Assad''s cousin to death", "summary": "A Syrian court in Damascus has sentenced Wassim al-Assad, a cousin of former Syrian ruler Bashar al-Assad, to death. He was found guilty of premeditated murder and torture. The conviction and sentencing occurred on Tuesday.", "summary_points": ["Wassim al-Assad, cousin of Syrian ruler Bashar al-Assad, sentenced to death.", "Convicted of premeditated murder and torture.", "Sentencing by a Damascus court on Tuesday.", "Wassim al-Assad is a former regime figure."], "title_hi": "सीरियाई अदालत ने बशर अल-असद के चचेरे भाई को मौत की सजा सुनाई", "summary_hi": "दमिश्क की एक सीरियाई अदालत ने पूर्व सीरियाई शासक बशर अल-असद के चचेरे भाई वासिम अल-असद को मौत की सजा सुनाई है। उन्हें पूर्व-नियोजित हत्या और यातना के आरोपों में दोषी पाया गया था। यह सजा मंगलवार को सुनाई गई।", "summary_points_hi": ["सीरियाई शासक बशर अल-असद के चचेरे भाई वासिम अल-असद को मौत की सजा सुनाई गई।", "उन्हें पूर्व-नियोजित हत्या और यातना के आरोपों में दोषी ठहराया गया।", "यह सजा मंगलवार को दमिश्क की एक अदालत ने सुनाई।", "वासिम अल-असद एक पूर्व शासन हस्ती हैं।"], "framing": {}, "framing_hi": {}, "topic": "Crime & Law", "region": "World", "published_at": null, "image_url": "https://s.france24.com/media/display/54d23416-9ae2-11f1-95e7-005056a97e36/w:1024/p:16x9/000-639D2KD-1.jpg", "sources": [{"source": "Al Jazeera English", "owner": "Al Jazeera English", "lean": "left", "language": "en", "url": "https://www.aljazeera.com/news/2026/8/18/syrian-court-sentences-wassim-al-assad-to?traffic_source=rss", "head